import{_ as l,a as e}from"./chunks/6_paint_20200521175459.xRqAujek.js";import{_ as s,o as i,c as n,a0 as r}from"./chunks/framework.DqMqoJl9.js";const o="/assets/6_paint_20200107164141.DwCrP6OT.png",t="/assets/6_paint_20200107164228.DrjeHwis.png",f=JSON.parse('{"title":"回流与重绘","description":"","frontmatter":{},"headers":[],"relativePath":"performance/old/6_paint.md","filePath":"performance/old/6_paint.md","lastUpdated":1791573371000}'),p={name:"performance/old/6_paint.md"};function c(d,a,h,u,b,m){return i(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="回流与重绘" tabindex="-1">回流与重绘 <a class="header-anchor" href="#回流与重绘" aria-label="Permalink to &quot;回流与重绘&quot;">​</a></h1><h2 id="_1-css-会让-js-变慢" tabindex="-1">1 css 会让 js 变慢 <a class="header-anchor" href="#_1-css-会让-js-变慢" aria-label="Permalink to &quot;1 css 会让 js 变慢&quot;">​</a></h2><p>频繁触发重绘与回流，会导致 UI 频繁渲染，最终导致 js 变慢</p><h2 id="_2-回流和重绘的概念" tabindex="-1">2 回流和重绘的概念 <a class="header-anchor" href="#_2-回流和重绘的概念" aria-label="Permalink to &quot;2 回流和重绘的概念&quot;">​</a></h2><h3 id="_2-1-回流" tabindex="-1">2.1 回流 <a class="header-anchor" href="#_2-1-回流" aria-label="Permalink to &quot;2.1 回流&quot;">​</a></h3><ul><li>当 render tree 中的一部分（或全部）因为元素的规模尺寸、布局、隐藏等改变而需要重新构建。这就称为回流</li><li>当页面的布局和几何属性改变时，就需要回流</li></ul><p>会触发回流的 css 属性：</p><ul><li>盒子模型相关属性。width, height, padding, margin, display, border, min-height</li><li>定位属性和浮动。top, bottom, left, right, position, float, clear</li><li>改变节点内部文字结构。text-aligin, overflow, font-weight, font-family, line-height, vertival-aligin, font-size</li></ul><h3 id="_2-2-重绘" tabindex="-1">2.2 重绘 <a class="header-anchor" href="#_2-2-重绘" aria-label="Permalink to &quot;2.2 重绘&quot;">​</a></h3><ul><li>当 render tree 中的一些元素需要更新属性，而这些属性只是影响元素的外观，风格，而不会影响布局的，比如 <code>background-color</code>。这就称为重绘</li></ul><p><strong>回流一定会引起重绘，而重绘不一定会引起回流</strong></p><p>只触发重绘的 css 属性：</p><p>color, border-style, border-radius, visibility, text-decoration, background, background-image, background-position, background-repeat, background-size, outline-color, outline-style, box-shadow</p><h2 id="_3-新建-dom-的过程" tabindex="-1">3 新建 DOM 的过程 <a class="header-anchor" href="#_3-新建-dom-的过程" aria-label="Permalink to &quot;3 新建 DOM 的过程&quot;">​</a></h2><ol><li>获取 DOM 后分割为多个图层</li><li>对每个图层的节点计算样式结果（recalculate style - 样式重计算）</li><li>为每个节点生成图形和位置（layout - 回流和重布局）</li><li>将每个节点绘制填充到图层位图中（paint - 重绘）</li><li>图层作为纹理上传到 GPU</li><li>合成多个图层到页面上生成最终屏幕图像（composite layers - 图层重组）</li></ol><blockquote><p>重绘和回流是以图层为单位的</p></blockquote><p>将频繁重绘回流的 DOM 元素单独作为一个独立图层，那么这个 DOM 元素的重绘和回流的影响只会在这个图层中。</p><p>但是图层并不是越多越好，图层的合成运算量是比较大的，如果图层太多的话就会在 composite layers 这里消耗大量的性能，这点也是需要极力避免的。</p><h2 id="_4-chrome-创建图层的条件" tabindex="-1">4 chrome 创建图层的条件 <a class="header-anchor" href="#_4-chrome-创建图层的条件" aria-label="Permalink to &quot;4 chrome 创建图层的条件&quot;">​</a></h2><ul><li>3D 或透视变换 CSS 属性（perspective transfrom）</li><li>使用加速视频解码的 video 节点 (浏览器会对 video 的每一帧进行重绘，所以能看到连续的视频)</li><li>拥有 3D (WebGl) 上下文或加速 2D 上下文的 canvas 节点</li><li>混合插件 (如 flash)</li><li>对自己的 opacity 做 CSS 动画或使用一个动画 webkit 变换的元素</li><li>拥有加速 CSS 过滤器的元素 (translate 3d)</li><li>元素拥有一个 z-index 较低且包含一个复合层的兄弟元素 (即有兄弟元素，有 z-index)</li></ul><p>gif 图会持续的触发重绘，但是不会创建新的图层</p><h2 id="_5-优化思路" tabindex="-1">5 优化思路 <a class="header-anchor" href="#_5-优化思路" aria-label="Permalink to &quot;5 优化思路&quot;">​</a></h2><ul><li>使用 translate 代替 top，top 会触发 layout 但 translate 不会</li><li>使用 opacity 代替 visibility，独立图层情况下，visibility 会触发重绘但是 opacity 不会</li><li>不要一条条修改 DOM 样式，预先定义好 class 然后修改 DOM 的 className，因为每修改一条样式都会触发重绘</li><li>把 DOM 离线后修改，display: none，后续修改都不会重绘</li><li>不要把 DOM 的属性值放在循环里，当成循环的变量。比如获取 offsetHeight 时，会触发回流。因为需要刷新缓冲区域，去获取真实的值</li><li>不要使用 table 布局，可能一个小改动会造成整个 table 的重新布局</li><li>动画实现速度的选择，UI 线程和 js 线程是相互阻塞的，css 动画会影响 js 运行</li><li>动画区域使用新图层</li><li>启动 GPU 硬件加速</li></ul><h2 id="_6-performance-工具" tabindex="-1">6 performance 工具 <a class="header-anchor" href="#_6-performance-工具" aria-label="Permalink to &quot;6 performance 工具&quot;">​</a></h2><p>Chrome 的开发者工具各有自己的侧重点，如 Network 工具的瀑布图有着资源拉取顺序的详细信息，它的侧重点在于分析网路链路。而 Performance 工具的侧重点则在于前端渲染过程，它拥有帧率条形图、CPU 使用率面积图、资源瀑布图、主线程火焰图、事件总揽等模块，它们和渲染息息相关，善用它们可以清晰地观察整个渲染阶段</p><p>performance 工具如下图：</p><p><img src="'+l+'" alt=""></p><p>参考下面文章：</p><p><a href="https://juejin.im/post/5b65105f5188251b134e9778" target="_blank" rel="noreferrer">https://juejin.im/post/5b65105f5188251b134e9778</a></p><p><a href="https://developers.google.com/web/tools/chrome-devtools/evaluate-performance" target="_blank" rel="noreferrer">https://developers.google.com/web/tools/chrome-devtools/evaluate-performance</a></p><p>下面搬运一点这篇文章的内容：</p><p>跟页面性能挂勾比较深的几个维度是：网络链路、服务器资源、前端渲染效率、客户端硬件</p><p>这几个维度不是互不相关的，反而是犬牙交错的关系。例如渲染过程中浏览器反应很慢，有可能是脚本写得太烂遭遇性能瓶颈，也有可能是应用开太多或者正在打游戏占用了过多计算机资源</p><p><strong>控制面板选项：</strong></p><ul><li>Network 限制网速</li><li>CPU 限制 CPU 资源</li><li>Disable JavaScript samples 使工具忽略记录 JS 的调用栈</li><li>Enable advanced paint instrumentation 详细记录某些渲染事件的细节</li></ul><p><strong>CPU 面积图：</strong></p><ul><li>蓝色：加载（Loading）事件</li><li>黄色：脚本运算（Scripting）事件</li><li>紫色：渲染（Rendering）事件</li><li>绿色：绘制（Painting）事件</li><li>灰色：其他（Other）</li><li>闲置：浏览器空闲</li></ul><p><strong>Frames：</strong></p><p>帧线程，可以看到每一次渲染的页面，鼠标悬浮绿色块可以看到 fps</p><p><strong>渲染事件：</strong></p><ul><li>Parse HTML 解析 HTML</li><li>Evaluate Script 执行 JavaScript</li><li>Recalculate style 计算样式</li><li>Layout 计算每个节点在屏幕中的精确位置和大小</li><li>Update Layer Tree</li><li>Paint 绘制到图层</li><li>Composite Layers 渲染引擎合成图层最终人眼可见</li></ul><h2 id="_7-rendering-工具" tabindex="-1">7 rendering 工具 <a class="header-anchor" href="#_7-rendering-工具" aria-label="Permalink to &quot;7 rendering 工具&quot;">​</a></h2><p>这个工具可以很直观的观察页面的渲染情况：</p><p><img src="'+e+`" alt=""></p><ul><li>Paint flashing 高亮重绘区域</li><li>Layout Shift Regions 高亮移动的区域</li><li>Layer borders 显示图层组合边界</li><li>FPS meter 显示帧率</li><li>Scrolling performance issues 高亮显示影响滚动的元素</li><li>Highlight ad frames</li><li>Hit-test borders</li></ul><h2 id="_8-实例" tabindex="-1">8 实例 <a class="header-anchor" href="#_8-实例" aria-label="Permalink to &quot;8 实例&quot;">​</a></h2><h3 id="_8-1-重绘" tabindex="-1">8.1 重绘 <a class="header-anchor" href="#_8-1-重绘" aria-label="Permalink to &quot;8.1 重绘&quot;">​</a></h3><p>只改变元素的背景颜色，观察 performance 工具中的渲染情况</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 改变元素的背景颜色</span></span>
<span class="line"><span style="color:#24292E;">box1.</span><span style="color:#6F42C1;">addEventListener</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;click&#39;</span><span style="color:#24292E;">, () </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">  box1.style.backgroundColor </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;#00f&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><img src="`+o+`" alt=""></p><h3 id="_8-2-回流" tabindex="-1">8.2 回流 <a class="header-anchor" href="#_8-2-回流" aria-label="Permalink to &quot;8.2 回流&quot;">​</a></h3><p>改变元素的 left 值，这时应该会触发回流</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 改变元素的 left 值</span></span>
<span class="line"><span style="color:#24292E;">box1.</span><span style="color:#6F42C1;">addEventListener</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;click&#39;</span><span style="color:#24292E;">, () </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">  box1.style.left </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;100px&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><img src="`+t+'" alt=""></p><p>上图可以看到，点击按钮后有一次 Layout，说明页面进行了重绘</p>',55)])])}const y=s(p,[["render",c]]);export{f as __pageData,y as default};
